using System;
using System.Collections.Generic;
using System.Linq;
using System.Net;
using System.Net.Mail;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

namespace EmailService
{
    public class FeatureFlags
    {
        private readonly Dictionary<string, bool> _flags;

        public FeatureFlags()
        {
            _flags = new Dictionary<string, bool>
            {
                { "rate_limiting", true },
                { "admin_notifications", true },
                { "audit_logging", true },
                { "api_key_rotation", false }
            };
        }

        public bool IsEnabled(string flag) => _flags.ContainsKey(flag) && _flags[flag];
    }

    public class ApiKeyStore
    {
        private readonly Dictionary<string, string> _keys;

        public ApiKeyStore()
        {
            // Load API keys from environment/configuration rather than hardcoding them.
            // Expected environment variables:
            //   APIKEY_SERVICE_ALPHA, APIKEY_SERVICE_BETA, APIKEY_ADMIN_PANEL
            _keys = new Dictionary<string, string>();

            AddKeyFromEnvironment("service_alpha", "APIKEY_SERVICE_ALPHA");
            AddKeyFromEnvironment("service_beta", "APIKEY_SERVICE_BETA");
            AddKeyFromEnvironment("admin_panel", "APIKEY_ADMIN_PANEL");
        }

        private void AddKeyFromEnvironment(string serviceId, string environmentVariable)
        {
            string value = Environment.GetEnvironmentVariable(environmentVariable);
            if (!string.IsNullOrEmpty(value))
            {
                _keys[serviceId] = value;
            }
        }

        public bool ValidateKey(string providedKey, string serviceId)
        {
            if (!_keys.ContainsKey(serviceId))
                return false;

            string storedKey = _keys[serviceId];
            return CompareKeys(storedKey, providedKey);
        }

        private bool CompareKeys(string expected, string actual)
        {
            if (expected == null || actual == null)
                return false;

            byte[] expectedBytes = Encoding.UTF8.GetBytes(expected);
            byte[] actualBytes = Encoding.UTF8.GetBytes(actual);

            return CryptographicOperations.FixedTimeEquals(expectedBytes, actualBytes);
        }
    }

    public class RateLimiter
    {
        private readonly Dictionary<string, List<DateTime>> _requests = new();
        private readonly int _maxRequests;
        private readonly TimeSpan _window;

        public RateLimiter(int maxRequests = 100, int windowSeconds = 3600)
        {
            _maxRequests = maxRequests;
            _window = TimeSpan.FromSeconds(windowSeconds);
        }

        public bool IsAllowed(string clientId)
        {
            var now = DateTime.UtcNow;
            if (!_requests.ContainsKey(clientId))
                _requests[clientId] = new List<DateTime>();

            _requests[clientId] = _requests[clientId]
                .Where(t => now - t < _window).ToList();

            if (_requests[clientId].Count >= _maxRequests)
                return false;

            _requests[clientId].Add(now);
            return true;
        }
    }

    public class EmailRequest
    {
        public string ServiceId { get; set; }
        public string ApiKey { get; set; }
        public string To { get; set; }
        public string Subject { get; set; }
        public string Body { get; set; }
    }

    public class EmailService
    {
        private readonly FeatureFlags _features;
        private readonly ApiKeyStore _keyStore;
        private readonly RateLimiter _rateLimiter;
        private readonly List<string> _auditLog = new();

        public EmailService()
        {
            _features = new FeatureFlags();
            _keyStore = new ApiKeyStore();
            _rateLimiter = new RateLimiter();
        }

        public async Task<SendResult> SendEmailAsync(EmailRequest request)
        {
            // Step 1: Authenticate
            var authResult = AuthenticateRequest(request);
            if (!authResult.Success)
                return new SendResult { Success = false, Error = authResult.Error };

            // Step 2: Rate limiting
            if (_features.IsEnabled("rate_limiting"))
            {
                if (!_rateLimiter.IsAllowed(request.ServiceId))
                    return new SendResult { Success = false, Error = "Rate limit exceeded" };
            }

            // Step 3: Send email
            try
            {
                await DispatchEmail(request);
                LogAudit(request, true);
                return new SendResult { Success = true };
            }
            catch (Exception ex)
            {
                LogAudit(request, false);
                return new SendResult { Success = false, Error = "Delivery failed" };
            }
        }

        private AuthResult AuthenticateRequest(EmailRequest request)
        {
            if (string.IsNullOrEmpty(request.ServiceId) || string.IsNullOrEmpty(request.ApiKey))
                return new AuthResult { Success = false, Error = "Missing credentials" };

            if (!_keyStore.ValidateKey(request.ApiKey, request.ServiceId))
                return new AuthResult { Success = false, Error = "Invalid API key" };

            return new AuthResult { Success = true };
        }

        private async Task DispatchEmail(EmailRequest request)
        {
            // Simulated email dispatch
            await Task.Delay(50);
        }

        private void LogAudit(EmailRequest request, bool success)
        {
            if (_features.IsEnabled("audit_logging"))
            {
                _auditLog.Add($"{DateTime.UtcNow:O}|{request.ServiceId}|{request.To}|{success}");
            }
        }
    }

    public class AuthResult
    {
        public bool Success { get; set; }
        public string Error { get; set; }
    }

    public class SendResult
    {
        public bool Success { get; set; }
        public string Error { get; set; }
    }
}
